import base64, pathlib, subprocess, zlib

PATCH = ''''''
patch_path = pathlib.Path('/tmp/v16-audit-fixes.patch')
patch_path.write_bytes(zlib.decompress(base64.b64decode(PATCH)))
subprocess.run(['git', 'apply', '--check', str(patch_path)], check=True)
subprocess.run(['git', 'apply', str(patch_path)], check=True)
